// 11.10.2026 подтверждено на iPhone (F-91 עבר QA): תהילים ל״ט — «הקראה: בודק QA · אושרה על ידי מנהל תוכן», «השמע»→«השהה», пауза/продолжение. Запись (tehilim39.mp3, 55 с) грузится только в web-админке (F-92 #6a86f7ed9d38).
// Тикеты #6a86f7eda7b2 (F-91) и #6a86f7ed9d38 (F-92), проверены на web 07.10.2026: «תהילים ל״ט ✅» (session.json).
// Скрины: pg-8-t39-no-recording (без записи «אין הקראה לפרק הזה»), pg-6-t39-user-before-play / pg-6-t39-playing («השהה», «הקראה: … · אושרה על ידי …»).
// Опора: F-91 AC1/AC3/AC4, S-25 AC1 «ההקראה מופעלת רק בפעולה יזומה של המשתמש ולא אוטומטית», FL-05. pending-app-2026-10-07.md п.7.
// Состояние зависит от админки: запись на תהילים ל״ט загружает и утверждает админ в /admin.
// RC-04a — когда записи нет; RC-04b — когда есть. Один из двух всегда пропускается с причиной.
import { expect } from '@wdio/globals';
import { byText, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { openTehilimChapter, playerButton, recordingLine, shown, skipWith, NO_RECORDING } from '../_lib/app-0710.ts';

const PLAY_END_TIMEOUT = 120000;

describe('Озвучка: экран תהילים', () => {
  afterEach(async () => { await toHome(); });

  it('RC-04a תהילים ל״ט без записи: «אין הקראה לפרק הזה», «השמע» неактивна #6a86f7eda7b2 #6a86f7ed9d38 @prod-safe', async function () {
    await openTehilimChapter(39);
    await scrollToText('האזן להקראה');
    if (await shown(recordingLine())) skipWith(this, 'у תהילים ל״ט есть утверждённая запись — состояние «без записи» неприменимо (см. RC-04b)');
    await expectVisibleText('אין הקראה לפרק הזה');
    await expect(await playerButton('השמע')).toBeDisabled();
    await expect(byText('השהה')).not.toBeDisplayed();
    // Чтение не заблокировано (S-25 AC3): кнопка «סיים קריאה» на месте.
    await expect(byText('סיים קריאה')).toBeDisplayed();
  });

  it('RC-04b תהילים ל״ט с записью: без автозапуска, «השמע» → «השהה» → пауза/продолжение → конец #6a86f7eda7b2 #6a86f7ed9d38 @prod-safe @manual-check', async function () {
    await openTehilimChapter(39);
    await scrollToText('האזן להקראה');
    if (!(await shown(recordingLine()))) skipWith(this, `${NO_RECORDING} (תהילים ל״ט)`);

    // 1. Строка «הקראה: … · אושרה על ידי …»; запись сама не играет (S-25 AC1).
    await expect(recordingLine()).toHaveText(/אושרה על ידי/);
    await expect(await playerButton('השמע')).toBeEnabled();
    await expect(byText('השהה')).not.toBeDisplayed();

    // 2. «השמע» → «השהה» → пауза «השמע» → продолжение «השהה» (с того же места — на слух) (F-91 AC3).
    await (await playerButton('השמע')).click();
    await expect(await playerButton('השהה')).toBeDisplayed();
    await (await playerButton('השהה')).click();
    await expect(await playerButton('השמע')).toBeDisplayed();
    await (await playerButton('השמע')).click();
    await expect(await playerButton('השהה')).toBeDisplayed();

    // 3. Конец записи — снова «השמע»; экран тот же פרק.
    await (await byText('השמע')).waitForDisplayed({ timeout: PLAY_END_TIMEOUT });
    await expect(byText('תהילים ל״ט')).toBeDisplayed();
  });
});
